const x=$('Preparar contexto seguro').first().json,r=$input.first().json;
let data;try{data=JSON.parse((r.candidates?.[0]?.content?.parts??[]).map(p=>p.text??'').join('').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));}catch{throw new Error('Transcrição indisponível.');}
const text=String(data.transcript??'').trim();
if(data.intelligible!==true||!text)return [{json:{...x,route:'reply',financialStatus:'audio_inaudivel',replyText:'Não consegui entender a fala desse áudio. Pode gravar novamente, um pouco mais perto do microfone?'}}];
if(text.length>6000)throw new Error('Transcrição muito longa.');
return [{json:{...x,text,mediaKind:'text',originalMediaKind:'audio',audioTranscribed:true,mediaExtracted:true}}];
